Q() { docker exec -i xnova-database psql -U postgres -d postgres -At -c "$1" < /dev/null; }
echo "== planets cols"; Q "select string_agg(column_name, ', ' order by ordinal_position) from information_schema.columns where table_schema='public' and table_name='planets'"
echo "== planet_resources cols"; Q "select string_agg(column_name, ', ' order by ordinal_position) from information_schema.columns where table_schema='public' and table_name='planet_resources'"
echo "== profiles some cols"; Q "select string_agg(column_name, ', ') from information_schema.columns where table_schema='public' and table_name='profiles' and column_name in ('username','referred_by','is_admin','fxu_balance','battles_won','battles_lost','battles_draw','units_destroyed','units_lost','debris_metal_total','debris_crystal_total','vacation_mode')"
echo "== secdef"; Q "select proname, prosecdef, proowner::regrole from pg_proc where pronamespace='public'::regnamespace and proname in ('process_fleet_arrival','process_acs_fleet_arrival','perform_combat','perform_acs_combat','validate_fleet_mission','process_user_fleets','process_all_pending_fleets','process_user_pending_fleets','join_acs_with_fleet','secure_send_fleet','send_fleet','calculate_and_sync_resources_internal','get_live_tung_price_usd','contribute_to_jackpot','record_admin_revenue','process_expedition') order by 1"
echo "== admin_revenue check"; Q "select pg_get_constraintdef(oid) from pg_constraint where conrelid='public.admin_revenue'::regclass and contype='c'"
echo "== first BEGIN context for guard targets"; for f in create_market_listing purchase_market_listing fulfill_buy_offer galaxy_navigate purchase_supply_box launch_missiles deploy_to_fortress create_colony_listing purchase_colony_listing secure_abandon_colony secure_demolish_building update_production_percentages refill_colony_resources purchase_instant_unit purchase_ship_blueprint secure_add_to_building_queue secure_activate_building_queue secure_add_to_shipyard_queue secure_start_research set_planet_autopilot_enabled secure_send_fleet join_acs_with_fleet create_buy_offer; do
  Q "select '$f', p.oid::regprocedure, l.lanname, (select count(*) from regexp_matches(pg_get_functiondef(p.oid), E'\\\\n[ \\\\t]+BEGIN\\\\M', 'g')) as indented_begins, position(E'\\nBEGIN' in pg_get_functiondef(p.oid)) > 0 as has_col0_begin, array_to_string(p.proargnames, ',') from pg_proc p join pg_language l on l.oid=p.prolang where p.pronamespace='public'::regnamespace and p.proname='$f'"
done
